values ('restaurant-words', 'restaurant', 'words', 'basic', 'رستوران و کافه: واژه‌ها', 'همهٔ واژه‌هایی که در کافه و رستوران می‌بینی و می‌شنوی: آدم‌ها و جاها، منو، نوشیدنی‌ها و غذاها، ظرف‌های روی میز، مزه‌ها، رژیم غذایی و حساب.', '🍽️', 16, '["جاها و آدم‌ها","بخش‌های رستوران","منو و وعده‌ها","نوشیدنی‌ها","غذاها","خوراکی‌های کافه","روی میز","مزه و حالت غذا","پخت و رژیم غذایی","حساب و پرداخت","فعل‌ها","چند واژهٔ پرکاربرد"]'::jsonb, false, 'de', 'fa')
